import sys, math
def is_prime(n):
    if n < 2: return False
    for i in range(2, int(math.isqrt(n)) + 1):
        if n % i == 0: return False
    return True

line = sys.stdin.read().strip()
if line:
    n = int(line)
    print('YES' if is_prime(n) else 'NO')

PRIME_CHECK.correct_cpp:
#include <iostream>
using namespace std;
bool isPrime(long long n) {
    if (n < 2) return false;
    for (long long i = 2; i * i <= n; i++) {
        if (n % i == 0) return false;
    }
    return true;
}
int main() {
    long long n;
    if (cin >> n) {
        cout << (isPrime(n) ? "YES" : "NO") << endl;
    }
    return 0;
}

