#include <iostream>
#include <string>
using namespace std;
int main() {
    string s;
    if (cin >> s) {
        int l = 0, r = s.length() - 1;
        bool ok = true;
        while (l < r) {
            if (s[l++] != s[r--]) { ok = false; break; }
        }
        cout << (ok ? "YES" : "NO") << endl;
    }
    return 0;
}

